    17	type MultipleAvatarsProps = {
    18	    /** Array of avatar URLs or icons */
    19	    icons: Icon[];
    20	
    21	    /** Set the size of avatars */
    22	    size?: ValueOf<typeof CONST.AVATAR_SIZE>;
    23	
    24	    /** Style for Second Avatar */
    25	    secondAvatarStyle?: StyleProp<ViewStyle>;
    26	
    27	    /** A fallback avatar icon to display when there is an error on loading avatar from remote URL. */
    28	    fallbackIcon?: AvatarSource;
    29	
    30	    /** Prop to identify if we should load avatars vertically instead of diagonally */
    31	    shouldStackHorizontally?: boolean;
    32	
    33	    /** Prop to identify if we should display avatars in rows */
    34	    shouldDisplayAvatarsInRows?: boolean;
    35	
    36	    /** Whether the avatars are hovered */
    37	    isHovered?: boolean;
    38	
    39	    /** Whether the avatars are in an element being pressed */
    40	    isPressed?: boolean;
    41	
    42	    /** Whether #focus mode is on */
    43	    isFocusMode?: boolean;
    44	
    45	    /** Whether avatars are displayed within a reportAction */
    46	    isInReportAction?: boolean;
    47	
    48	    /** Whether to show the tooltip text */
    49	    shouldShowTooltip?: boolean;
    50	
    51	    /** Whether avatars are displayed with the highlighted background color instead of the app background color. This is primarily the case for IOU previews. */
    52	    shouldUseCardBackground?: boolean;
    53	
    54	    /** Prop to limit the amount of avatars displayed horizontally */
    55	    maxAvatarsInRow?: number;
    56	};
    57	
    58	type AvatarStyles = {
    59	    singleAvatarStyle: ViewStyle & ImageStyle;
    60	    secondAvatarStyles: ViewStyle & ImageStyle;
    61	};
    62	
    63	type AvatarSizeToStyles = typeof CONST.AVATAR_SIZE.SMALL | typeof CONST.AVATAR_SIZE.LARGE | typeof CONST.AVATAR_SIZE.DEFAULT;
    64	
    65	type AvatarSizeToStylesMap = Record<AvatarSizeToStyles, AvatarStyles>;
    66	
    67	function MultipleAvatars({
    68	    fallbackIcon,
    69	    icons = [],
    70	    size = CONST.AVATAR_SIZE.DEFAULT,
    71	    secondAvatarStyle: secondAvatarStyleProp,
    72	    shouldStackHorizontally = false,
    73	    shouldDisplayAvatarsInRows = false,
    74	    isHovered = false,
    75	    isPressed = false,
    76	    isFocusMode = false,
    77	    isInReportAction = false,
    78	    shouldShowTooltip = true,
    79	    shouldUseCardBackground = false,
    80	    maxAvatarsInRow = CONST.AVATAR_ROW_SIZE.DEFAULT,
    81	}: MultipleAvatarsProps) {
    82	    const theme = useTheme();
    83	    const styles = useThemeStyles();
    84	    const StyleUtils = useStyleUtils();
    85	
    86	    const avatarSizeToStylesMap: AvatarSizeToStylesMap = useMemo(
    87	        () => ({
    88	            [CONST.AVATAR_SIZE.SMALL]: {
    89	                singleAvatarStyle: styles.singleAvatarSmall,
    90	                secondAvatarStyles: styles.secondAvatarSmall,
    91	            },
    92	            [CONST.AVATAR_SIZE.LARGE]: {
    93	                singleAvatarStyle: styles.singleAvatarMedium,
    94	                secondAvatarStyles: styles.secondAvatarMedium,
    95	            },
    96	            [CONST.AVATAR_SIZE.DEFAULT]: {
    97	                singleAvatarStyle: styles.singleAvatar,
    98	                secondAvatarStyles: styles.secondAvatar,
    99	            },
   100	        }),
   101	        [styles],
   102	    );
   103	    const secondAvatarStyle = secondAvatarStyleProp ?? [StyleUtils.getBackgroundAndBorderStyle(isHovered ? theme.activeComponentBG : theme.componentBG)];
   104	
   105	    let avatarContainerStyles = StyleUtils.getContainerStyles(size, isInReportAction);
   106	    const {singleAvatarStyle, secondAvatarStyles} = useMemo(() => avatarSizeToStylesMap[size as AvatarSizeToStyles] ?? avatarSizeToStylesMap.default, [size, avatarSizeToStylesMap]);
   107	
   108	    const tooltipTexts = useMemo(() => (shouldShowTooltip ? icons.map((icon) => icon.name) : ['']), [shouldShowTooltip, icons]);
   109	    const avatarSize = useMemo(() => {
   110	        if (isFocusMode) {
   111	            return CONST.AVATAR_SIZE.MID_SUBSCRIPT;
   112	        }
   113	
   114	        if (size === CONST.AVATAR_SIZE.LARGE) {
   115	            return CONST.AVATAR_SIZE.MEDIUM;
   116	        }
   117	
   118	        return CONST.AVATAR_SIZE.SMALLER;
   119	    }, [isFocusMode, size]);
   120	
   121	    const avatarRows = useMemo(() => {
   122	        // If we're not displaying avatars in rows or the number of icons is less than or equal to the max avatars in a row, return a single row
   123	        if (!shouldDisplayAvatarsInRows || icons.length <= maxAvatarsInRow) {
   124	            return [icons];
   125	        }
   126	
   127	        // Calculate the size of each row
   128	        const rowSize = Math.min(Math.ceil(icons.length / 2), maxAvatarsInRow);
   129	
   130	        // Slice the icons array into two rows
   131	        const firstRow = icons.slice(0, rowSize);
   132	        const secondRow = icons.slice(rowSize);
   133	
   134	        // Update the state with the two rows as an array
   135	        return [firstRow, secondRow];
   136	    }, [icons, maxAvatarsInRow, shouldDisplayAvatarsInRows]);
   137	
   138	    if (!icons.length) {
   139	        return null;
   140	    }
   141	
   142	    if (icons.length === 1 && !shouldStackHorizontally) {
   143	        return (
   144	            <UserDetailsTooltip
   145	                accountID={Number(icons[0].id)}
   146	                icon={icons[0]}
   147	                fallbackUserDetails={{
   148	                    displayName: icons[0].name,
   149	                }}
   150	            >
   151	                <View style={avatarContainerStyles}>
   152	                    <Avatar
   153	                        source={icons[0].source}
   154	                        size={size}
   155	                        fill={icons[0].fill}
   156	                        name={icons[0].name}
   157	                        avatarID={icons[0].id}
   158	                        type={icons[0].type}
   159	                        fallbackIcon={icons[0].fallbackIcon}
   160	                    />
   161	                </View>
   162	            </UserDetailsTooltip>
   163	        );
   164	    }
   165	
   166	    const oneAvatarSize = StyleUtils.getAvatarStyle(size);
   167	    const oneAvatarBorderWidth = StyleUtils.getAvatarBorderWidth(size).borderWidth ?? 0;
   168	    const overlapSize = oneAvatarSize.width / 3;
   169	
   170	    if (shouldStackHorizontally) {
   171	        // Height of one avatar + border space
   172	        const height = oneAvatarSize.height + 2 * oneAvatarBorderWidth;
   173	        avatarContainerStyles = StyleUtils.combineStyles([styles.alignItemsCenter, styles.flexRow, StyleUtils.getHeight(height)]);
   174	    }
   175	
   176	    return shouldStackHorizontally ? (
   177	        avatarRows.map((avatars, rowIndex) => (
   178	            <View
   179	                style={avatarContainerStyles}
   180	                /* eslint-disable-next-line react/no-array-index-key */
   181	                key={`avatarRow-${rowIndex}`}
   182	            >
   183	                {[...avatars].splice(0, maxAvatarsInRow).map((icon, index) => (
   184	                    <UserDetailsTooltip
   185	                        key={`stackedAvatars-${icon.id}`}
   186	                        accountID={Number(icon.id)}
   187	                        icon={icon}
   188	                        fallbackUserDetails={{
   189	                            displayName: icon.name,
   190	                        }}
   191	                    >
   192	                        <View style={[StyleUtils.getHorizontalStackedAvatarStyle(index, overlapSize), StyleUtils.getAvatarBorderRadius(size, icon.type)]}>
   193	                            <Avatar
   194	                                iconAdditionalStyles={[
   195	                                    StyleUtils.getHorizontalStackedAvatarBorderStyle({
   196	                                        theme,
   197	                                        isHovered,
   198	                                        isPressed,
   199	                                        isInReportAction,
   200	                                        shouldUseCardBackground,
   201	                                    }),
   202	                                    StyleUtils.getAvatarBorderWidth(size),
   203	                                ]}
   204	                                source={icon.source ?? fallbackIcon}
   205	                                size={size}
   206	                                name={icon.name}
   207	                                avatarID={icon.id}
   208	                                type={icon.type}
   209	                                fallbackIcon={icon.fallbackIcon}
   210	                            />
   211	                        </View>
   212	                    </UserDetailsTooltip>
   213	                ))}
   214	                {avatars.length > maxAvatarsInRow && (
   215	                    <Tooltip
   216	                        // We only want to cap tooltips to only 10 users or so since some reports have hundreds of users, causing performance to degrade.
   217	                        text={tooltipTexts.slice(avatarRows.length * maxAvatarsInRow - 1, avatarRows.length * maxAvatarsInRow + 9).join(', ')}
   218	                    >
   219	                        <View
   220	                            style={[
   221	                                styles.alignItemsCenter,
   222	                                styles.justifyContentCenter,
   223	                                StyleUtils.getHorizontalStackedAvatarBorderStyle({
   224	                                    theme,
   225	                                    isHovered,
   226	                                    isPressed,
   227	                                    isInReportAction,
   228	                                    shouldUseCardBackground,
   229	                                }),
   230	
   231	                                // Set overlay background color with RGBA value so that the text will not inherit opacity
   232	                                StyleUtils.getBackgroundColorWithOpacityStyle(theme.overlay, variables.overlayOpacity),
   233	                                StyleUtils.getHorizontalStackedOverlayAvatarStyle(oneAvatarSize, oneAvatarBorderWidth),
   234	                                icons[3].type === CONST.ICON_TYPE_WORKSPACE && StyleUtils.getAvatarBorderRadius(size, icons[3].type),
   235	                            ]}
   236	                        >
   237	                            <View style={[styles.justifyContentCenter, styles.alignItemsCenter, StyleUtils.getHeight(oneAvatarSize.height), StyleUtils.getWidthStyle(oneAvatarSize.width)]}>
   238	                                <Text
   239	                                    style={[styles.avatarInnerTextSmall, StyleUtils.getAvatarExtraFontSizeStyle(size), styles.userSelectNone]}
   240	                                    dataSet={{[CONST.SELECTION_SCRAPER_HIDDEN_ELEMENT]: true}}
   241	                                >{`+${avatars.length - maxAvatarsInRow}`}</Text>
   242	                            </View>
   243	                        </View>
   244	                    </Tooltip>
   245	                )}
   246	            </View>
   247	        ))
   248	    ) : (
   249	        <View style={avatarContainerStyles}>
   250	            <View style={[singleAvatarStyle, icons[0].type === CONST.ICON_TYPE_WORKSPACE && StyleUtils.getAvatarBorderRadius(size, icons[0].type)]}>
   251	                <UserDetailsTooltip
   252	                    accountID={Number(icons[0].id)}
   253	                    icon={icons[0]}
   254	                    fallbackUserDetails={{
   255	                        displayName: icons[0].name,
   256	                    }}
   257	                >
   258	                    {/* View is necessary for tooltip to show for multiple avatars in LHN */}
   259	                    <View>
   260	                        <Avatar
   261	                            source={icons[0].source ?? fallbackIcon}
   262	                            size={avatarSize}
   263	                            imageStyles={[singleAvatarStyle]}
   264	                            name={icons[0].name}
   265	                            type={icons[0].type}
   266	                            avatarID={icons[0].id}
   267	                            fallbackIcon={icons[0].fallbackIcon}
   268	                        />
   269	                    </View>
   270	                </UserDetailsTooltip>
   271	                <View style={[secondAvatarStyles, secondAvatarStyle, icons[1].type === CONST.ICON_TYPE_WORKSPACE ? StyleUtils.getAvatarBorderRadius(size, icons[1].type) : {}]}>
   272	                    {icons.length === 2 ? (
   273	                        <UserDetailsTooltip
   274	                            accountID={Number(icons[1].id)}
   275	                            icon={icons[1]}
   276	                            fallbackUserDetails={{
   277	                                displayName: icons[1].name,
   278	                            }}
   279	                        >
   280	                            <View>
   281	                                <Avatar
   282	                                    source={icons[1].source ?? fallbackIcon}
   283	                                    size={avatarSize}
   284	                                    imageStyles={[singleAvatarStyle]}
   285	                                    name={icons[1].name}
   286	                                    avatarID={icons[1].id}
   287	                                    type={icons[1].type}
   288	                                    fallbackIcon={icons[1].fallbackIcon}
   289	                                />
   290	                            </View>
   291	                        </UserDetailsTooltip>
   292	                    ) : (
   293	                        <Tooltip text={tooltipTexts.slice(1).join(', ')}>
   294	                            <View style={[singleAvatarStyle, styles.alignItemsCenter, styles.justifyContentCenter]}>
   295	                                <Text
   296	                                    style={[styles.userSelectNone, size === CONST.AVATAR_SIZE.SMALL ? styles.avatarInnerTextSmall : styles.avatarInnerText]}
   297	                                    dataSet={{[CONST.SELECTION_SCRAPER_HIDDEN_ELEMENT]: true}}
   298	                                >
